import java.io.*;
import java.util.*;

public class Main {
    static final boolean _DEBUG = false;
    static int debugLimit = 200;
    static int debugCounter = 0;

    static class InputReader {
        private BufferedReader reader;
        private StringTokenizer tokens;

        public InputReader(InputStream input) {
            reader = new BufferedReader(new InputStreamReader(input));
        }

        public String next() {
            while (tokens == null || !tokens.hasMoreTokens()) {
                try {
                    tokens = new StringTokenizer(reader.readLine());
                } catch (IOException e) {
                    e.printStackTrace();
                    return null;
                }
            }
            return tokens.nextToken();
        }

        public int nextInt() { return Integer.parseInt(next()); }
        public long nextLong() { return Long.parseLong(next()); }
        public double nextDouble() { return Double.parseDouble(next()); }
        public String nextLine() {
            try { return reader.readLine(); } catch (IOException e) { return ""; }
        }
    }

    static InputReader in;
    static PrintWriter out;

    static void debug(String msg) {
        if (_DEBUG && debugCounter < debugLimit) {
            out.println(msg);
            out.flush();
            debugCounter++;
        }
    }

    public static void main(String[] args) throws IOException {
        in = new InputReader(System.in);
        out = new PrintWriter(new BufferedWriter(new OutputStreamWriter(System.out)));
        Main app = new Main();
        app.run();
        out.close();
    }

    int rows, cols, maskBound;
    int[] popCounts;
    int[][][] stateDP;

    void run() {
        rows = in.nextInt();
        cols = in.nextInt();
        if (rows < cols) {
            int temp = rows;
            rows = cols;
            cols = temp;
        }
        maskBound = 1 << cols;
        popCounts = new int[maskBound];
        stateDP = new int[rows][maskBound][maskBound];

        for (int i = 0; i < rows; i++) {
            for (int j = 0; j < maskBound; j++) {
                Arrays.fill(stateDP[i][j], -1);
            }
        }

        for (int state = 0; state < maskBound; state++) {
            popCounts[state] = Integer.bitCount(state);
            stateDP[0][state][0] = popCounts[state];
        }

        int minCover = Integer.MAX_VALUE;

        for (int layer = 0; layer < rows - 1; layer++) {
            for (int prev2 = 0; prev2 < maskBound; prev2++) {
                for (int prev1 = 0; prev1 < maskBound; prev1++) {
                    if (stateDP[layer][prev2][prev1] == -1) continue;
                    for (int curr = 0; curr < maskBound; curr++) {
                        int covered = ((prev2 | (prev2 << 1) | (prev2 >> 1) | prev1 | curr) & (maskBound - 1));
                        if (covered == (maskBound - 1)) {
                            int newCost = stateDP[layer][prev2][prev1] + popCounts[curr];
                            if (stateDP[layer + 1][curr][prev1] == -1 || newCost < stateDP[layer + 1][curr][prev1]) {
                                stateDP[layer + 1][curr][prev1] = newCost;
                            }
                        }
                    }
                }
            }
        }

        for (int prev2 = 0; prev2 < maskBound; prev2++) {
            for (int prev1 = 0; prev1 < maskBound; prev1++) {
                if (stateDP[rows - 1][prev2][prev1] != -1) {
                    int finalCover = ((prev2 | (prev2 << 1) | (prev2 >> 1) | prev1) & (maskBound - 1));
                    if (finalCover == (maskBound - 1)) {
                        minCover = Math.min(minCover, stateDP[rows - 1][prev2][prev1]);
                    }
                }
            }
        }

        out.println(rows * cols - minCover);
    }
}
